input.command:
cd /workspace/dataset
objdump -s -j .gcc_except_table --start-address=0x411614 --stop-address=0x4116dc test5_executable > /tmp/lsda.txt
perl -e '
open F,"/tmp/lsda.txt"; my $hex="";
while(<F>){ if(/^\s*([0-9a-f]{6})\s((?:[0-9a-f]{2,8}\s){1,4})/){ my $h=$2; $h=~s/\s+//g; $hex.=$h; } }
my @b = map { hex } ($hex =~ /(..)/g);
my $p=0; my $base=0x411614; my $fs=0x404100;
sub uleb { my $r=0; my $s=0; while(1){ my $c=$b[$p++]; $r |= ($c & 0x7f) << $s; $s+=7; last unless $c & 0x80; } return $r; }
sub sleb { my $r=0; my $s=0; my $c; do { $c=$b[$p++]; $r |= ($c & 0x7f) << $s; $s+=7; } while ($c & 0x80); $r -= (1<<$s) if $c & 0x40; return $r; }
printf "LPStart enc = 0x%02x\n", $b[$p++];
printf "TType  enc = 0x%02x\n", $b[$p++];
my $ttoff = uleb(); my $ttbase = $base + $p + $ttoff;
printf "TTypeBase  = 0x%x (offset %d)\n", $ttbase, $ttoff;
printf "CS enc     = 0x%02x\n", $b[$p++];
my $cslen = uleb(); my $csend = $p + $cslen;
printf "CS tbl     = 0x%x .. 0x%x (len %d)\n", $base+$p, $base+$csend, $cslen;
my $target = 0x404658 - $fs;
printf "\nlooking for call-site region containing +0x%x (the std::stoi call)\n\n", $target;
while ($p < $csend) {
  my $st=uleb(); my $ln=uleb(); my $lp=uleb(); my $ac=uleb();
  my $hit = ($target >= $st && $target < $st+$ln) ? "   <=== CONTAINS stoi CALL" : "";
  printf "start=+0x%-5x len=0x%-4x lp=%-10s action=%d%s\n", $st,$ln, ($lp? sprintf("0x%x",$fs+$lp):"none"), $ac, $hit;
}
printf "\nAction table at 0x%x:\n", $base+$p;
my $ai=1;
while ($p < ($ttbase-$base)) {
  my $sp=$base+$p; my $f=sleb(); my $d=sleb();
  printf "  action#%d @0x%x: filter=%d next_disp=%d", $ai, $sp, $f, $d;
  if ($f==0){ print "  -> CLEANUP\n" } else {
    my $tp = $ttbase - $f*4;
    my @t = @b[($tp-$base)..($tp-$base+3)];
    my $v = $t[0] | $t[1]<<8 | $t[2]<<16 | $t[3]<<24;
    printf "  -> ttype[%d] @0x%x = 0x%08x %s\n", $f, $tp, $v, ($v==0 ? "== NULL  ==> catch (...)  CATCH-ALL" : "== typed catch");
  }
  $ai++; last if $p >= ($ttbase-$base);
}
'
